330	     * @param city the owner's city, used to resolve the region when the postcode does not
331	     * @return the canonical region string, or {@code "UNKNOWN"} when neither source resolves a region
332	     */
333	    private String deriveRegion(String postcode, String city) {
334	        if (postcode != null) {
335	            try {
336	                int value = Integer.parseInt(postcode.trim());
337	                for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
338	                    int[] range = entry.getValue();
339	                    if (value >= range[0] && value <= range[1]) {
340	                        return entry.getKey();
341	                    }
342	                }
343	            } catch (NumberFormatException ex) {
344	                // Not a numeric postcode; fall back to the city table below.
345	            }
346	        }
347	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
