359	            byte[] digest = MessageDigest.getInstance("SHA-256")
360	                .digest(input.getBytes(StandardCharsets.UTF_8));
361	            StringBuilder hex = new StringBuilder();
362	            for (int i = 0; i < 4; i++) {
363	                hex.append(String.format("%02X", digest[i]));
364	            }
365	            return hex.toString();
366	        } catch (NoSuchAlgorithmException ex) {
367	            throw new IllegalStateException("SHA-256 not available", ex);
368	        }
