458	        }
459	        if (!digits.matches("[0-9]{8,15}")) {
460	            throw new InvalidOwnerFieldsException(List.of("telephone"));
461	        }
462	        validateNationalNumberLength(digits);
463	        return "+" + digits;
464	    }
465	
466	    /**
467	     * Validates that the national-number portion of a normalized E.164 number (the digits after the
468	     * country calling code) has the exact length required for that country. The country code is matched
469	     * against {@link #NATIONAL_NUMBER_LENGTHS} (e.g. {@code +61} requires 9 national digits, {@code +1}
470	     * requires 10). Numbers whose country code is not listed are left to the generic length bounds.
471	     *
472	     * @param digits the normalized E.164 digits, without the leading {@code '+'}
473	     * @throws InvalidOwnerFieldsException if the national-number length is wrong for the country code
474	     */
475	    private void validateNationalNumberLength(String digits) {
476	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
477	            String countryCode = entry.getKey();
478	            if (digits.startsWith(countryCode)) {
479	                int nationalLength = digits.length() - countryCode.length();
480	                if (nationalLength != entry.getValue()) {
481	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
482	                }
483	                return;
484	            }
485	        }
486	    }
487	
488	    /**
489	     * Best-effort conversion of an existing telephone value to E.164 form for duplicate comparison,
490	     * returning {@code null} when the value cannot form a valid E.164 number.
491	     *
492	     * @param telephone an existing owner's stored telephone value
493	     * @return the E.164 form, or {@code null} if it cannot be normalized
494	     */
495	    private String toE164OrNull(String telephone) {
496	        try {
497	            return normalizeTelephone(telephone);
498	        } catch (InvalidOwnerFieldsException ex) {
499	            return null;
500	        }
501	    }
502	
503	    /**
504	     * Normalizes an optional owner email. A {@code null} value is left untouched (the field is optional).
505	     * When a value is present it must be a syntactically valid address (see {@link #EMAIL_PATTERN}); the
506	     * accepted value is trimmed and lower-cased before it is stored and returned.
507	     *
508	     * @param email the raw email value from the submitted owner payload, may be {@code null}
509	     * @return {@code null} if no email was supplied, otherwise the lower-cased email
510	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address
511	     */
512	    private String normalizeEmail(String email) {
513	        if (email == null) {
514	            return null;
515	        }
516	        String trimmed = email.strip();
517	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
518	            throw new InvalidOwnerFieldsException(List.of("email"));
519	        }
520	        return trimmed.toLowerCase(Locale.ROOT);
521	    }
522	
523	    /**
524	     * Rejects creating an owner whose derived identity key exactly equals that of any existing owner.
525	     * This single check consolidates the former separate telephone, email and household duplicate
526	     * checks: an owner is a duplicate only when its <em>whole</em> identity key
527	     * ({@code '<normalizedTelephone>|<email>|<householdId>'}) matches an existing owner's. Because the
528	     * telephone is part of the key, two members of the same household (same {@code householdId}) with
529	     * different telephones have different identity keys and are both allowed.
530	     *
531	     * <p>The new owner's telephone is already E.164-normalized and its email already lower-cased.
532	     * Existing owners' telephones are converted to E.164 form and their emails lower-cased before the
533	     * key is built, so differently-formatted representations of the same values still collide.
534	     *
535	     * @param owner the owner being created, whose email and household id contribute to the key
536	     * @param normalizedTelephone the E.164 telephone of the owner being created
537	     * @throws DuplicateOwnerIdentityException if another owner already has the same whole identity key
538	     */
539	    private void rejectDuplicateIdentity(Owner owner, String normalizedTelephone) {
540	        String newKey = identityKey(normalizedTelephone, owner.getEmail(), owner.getHouseholdId());
541	        boolean duplicate = this.clinicService.findAllOwners().stream()
542	            .anyMatch(existing -> newKey.equals(identityKey(
543	                toE164OrNull(existing.getTelephone()),
544	                existing.getEmail() == null ? null : existing.getEmail().toLowerCase(Locale.ROOT),
545	                existing.getHouseholdId())));
546	        if (duplicate) {
547	            throw new DuplicateOwnerIdentityException(newKey);
548	        }
549	    }
550	
551	    /**
552	     * Builds the duplicate-detection identity key, formatted
553	     * {@code '<normalizedTelephone>|<email>|<householdId>'}. The telephone, email and household-id
554	     * segments are each replaced with the empty string when {@code null}, so an absent email or
555	     * household id contributes an empty segment rather than the literal {@code "null"}.
556	     *
557	     * @param normalizedTelephone the E.164 telephone, may be {@code null}
558	     * @param email the lower-cased email, may be {@code null}
559	     * @param householdId the household id, may be {@code null}
560	     * @return the identity key
561	     */
562	    private String identityKey(String normalizedTelephone, String email, String householdId) {
563	        return (normalizedTelephone == null ? "" : normalizedTelephone)
564	            + "|" + (email == null ? "" : email)
565	            + "|" + (householdId == null ? "" : householdId);
566	    }
567	
568	    /**
569	     * The maximum number of owners a single city may contain. Once a city already holds this many
570	     * owners, creating another owner in that city is rejected.
571	     */
572	    private static final int MAX_OWNERS_PER_CITY = 50;
573	
574	    /**
575	     * Rejects creating an owner in a city that already contains {@link #MAX_OWNERS_PER_CITY} or more
576	     * owners. Existing owners' cities are compared case-insensitively with surrounding and repeated
577	     * internal whitespace collapsed (see {@link #normalizeForComparison}), matching the per-city
578	     * counting used elsewhere.
579	     *
580	     * @param city the city of the owner being created
581	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
582	     */
583	    /**
584	     * The maximum number of owners that may be registered on a single day. Once this many owners
585	     * already share a {@code registrationDate}, creating another owner for that day is rejected.
586	     */
587	    private static final int MAX_OWNERS_PER_DAY = 100;
588	
589	    /**
590	     * Rejects creating an owner on a day that has already reached {@link #MAX_OWNERS_PER_DAY} or more
591	     * owner registrations. Existing owners are counted by their {@code registrationDate} matching the
592	     * registration date of the owner being created.
593	     *
594	     * @param registrationDate the registration date of the owner being created
595	     * @throws DailyOwnerLimitExceededException if the day has already reached the maximum number of owners
596	     */
597	    /**
598	     * Rolls an effective registration date forward onto a business day. A registration date must fall
599	     * on a weekday: when the supplied or defaulted date is a Saturday or Sunday it is rolled forward to
600	     * the next Monday and that adjusted date becomes the owner's {@code registrationDate}. A weekday date
601	     * is returned unchanged. Every value derived from the registration date (the daily create-limit
602	     * count, the membership number's year segment, and so on) uses this adjusted date.
603	     *
604	     * @param date the effective registration date (supplied in the request or defaulted to the server date)
605	     * @return the same date if it is a weekday, otherwise the following Monday
606	     */
607	    /**
608	     * Rejects creating an owner whose supplied {@code registrationDate} is later than the server's
609	     * current date. A registration date is not permitted to lie in the future; a {@code null} date
610	     * (defaulted to the server date) and any date on or before today are accepted. The check runs
611	     * against the date exactly as supplied, before it is rolled forward onto a business day.
612	     *
613	     * @param registrationDate the registration date supplied in the request, may be {@code null}
614	     * @throws FutureRegistrationDateException if the supplied date is after the server date
615	     */
616	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
617	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
618	            throw new FutureRegistrationDateException(registrationDate);
619	        }
620	    }
621	
622	    private LocalDate rollToBusinessDay(LocalDate date) {
623	        DayOfWeek day = date.getDayOfWeek();
624	        if (day == DayOfWeek.SATURDAY) {
625	            return date.plusDays(2);
626	        }
627	        if (day == DayOfWeek.SUNDAY) {
628	            return date.plusDays(1);
629	        }
630	        return date;
631	    }
632	
633	    private void rejectDailyLimitReached(LocalDate registrationDate) {
634	        long ownersToday = this.clinicService.findAllOwners().stream()
635	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
636	            .count();
637	        if (ownersToday >= MAX_OWNERS_PER_DAY) {
638	            throw new DailyOwnerLimitExceededException(registrationDate);
639	        }
640	    }
641	
642	    /**
643	     * The number of owners that must already share a {@code registrationDate} before a newly created
644	     * owner for that day is flagged with a bulk-signup warning. Once more than this many owners have
645	     * been created for the day, the new owner's {@code bulkSignupWarning} is {@code true}.
646	     */
647	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
648	
649	    /**
650	     * Determines whether the owner being created should carry a bulk-signup warning. The warning is
651	     * raised when more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for
652	     * the same registration date at the time this owner is created. Existing owners are counted by their
653	     * {@code registrationDate} matching the registration date of the owner being created, mirroring the
654	     * daily create-limit accumulation.
655	     *
656	     * @param registrationDate the registration date of the owner being created
657	     * @return {@code true} if the day already holds more than the threshold number of owners
658	     */
659	    private boolean isBulkSignupDay(LocalDate registrationDate) {
660	        long ownersToday = this.clinicService.findAllOwners().stream()
661	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
662	            .count();
663	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
664	    }
665	
666	    private void rejectCityAtCapacity(String city) {
667	        String normalizedCity = normalizeForComparison(city);
668	        long ownersInCity = this.clinicService.findAllOwners().stream()
669	            .filter(existing -> normalizedCity.equals(normalizeForComparison(existing.getCity())))
670	            .count();
671	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
672	            throw new OwnerCityCapacityExceededException(city);
673	        }
674	    }
675	
676	    /**
677	     * Assigns the owner being created a household identifier when the request opts into sharing a
678	     * household. The identifier is a stable value derived from the owner's normalized last name and
679	     * address (see {@link #householdId}), so every owner in the same household is given the exact same
680	     * value regardless of creation order. Any already-existing owner in the same household that has no
681	     * identifier yet is back-filled with the same value so the whole household stays consistent.
682	     *
683	     * @param owner the owner being created, whose household id is set in place
684	     */
685	    private void assignHousehold(Owner owner) {
686	        String householdId = householdId(owner.getLastName(), owner.getAddress());
687	        String normalizedLastName = normalizeForComparison(owner.getLastName());
688	        String normalizedAddress = normalizeAddress(owner.getAddress());
689	        for (Owner existing : this.clinicService.findAllOwners()) {
690	            if (existing.getHouseholdId() == null
691	                && normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
692	                && normalizedAddress.equals(normalizeAddress(existing.getAddress()))) {
693	                existing.setHouseholdId(householdId);
694	                this.clinicService.saveOwner(existing);
695	            }
696	        }
697	        owner.setHouseholdId(householdId);
698	    }
699	
700	    /**
701	     * Counts how many owners belong to the household the owner being created has just been assigned to,
702	     * inclusive of that owner. Existing owners are matched by their {@code householdId} equalling the
703	     * given identifier; the owner being created is added on because it is counted before being persisted.
704	     * An owner that did not opt into a shared household (its {@code householdId} is {@code null}) is a
705	     * household of one. The value is snapshotted on the owner.
706	     *
707	     * @param householdId the household identifier assigned to the owner being created, may be {@code null}
708	     * @return the number of household members, including the owner being created
709	     */
710	    private int countHousehold(String householdId) {
711	        if (householdId == null) {
712	            return 1;
713	        }
714	        long existing = this.clinicService.findAllOwners().stream()
715	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
716	            .count();
717	        return (int) existing + 1;
718	    }
719	
720	    /**
721	     * Derives the stable household identifier for a given last name and address. The value is
722	     * {@code 'HH-' + <12 upper-case hex chars>} of the SHA-256 digest of the normalized last name and
723	     * address (see {@link #normalizeForComparison}), joined by a delimiter. Two owners that resolve to
724	     * the same household therefore always produce the same identifier.
725	     *
726	     * @param lastName the owner's last name
727	     * @param address the owner's address
728	     * @return the stable household identifier
729	     */
730	    private String householdId(String lastName, String address) {
731	        String key = normalizeForComparison(lastName) + "\n" + normalizeAddress(address);
732	        try {
733	            byte[] digest = MessageDigest.getInstance("SHA-256")
734	                .digest(key.getBytes(StandardCharsets.UTF_8));
735	            StringBuilder hex = new StringBuilder();
736	            for (int i = 0; i < 6; i++) {
737	                hex.append(String.format("%02X", digest[i]));
738	            }
739	            return "HH-" + hex;
740	        } catch (NoSuchAlgorithmException ex) {
741	            throw new IllegalStateException("SHA-256 not available", ex);
742	        }
743	    }
744	
745	    /**
746	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and trailing
747	     * whitespace is stripped, every run of internal whitespace is collapsed to a single space, and the
748	     * result is lower-cased. A {@code null} value normalizes to the empty string.
749	     *
750	     * @param value the value to normalize, may be {@code null}
751	     * @return the normalized value
752	     */
753	    private String normalizeForComparison(String value) {
754	        if (value == null) {
755	            return "";
756	        }
757	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
758	    }
759	
760	    /**
761	     * Normalizes an owner address for storage and comparison: leading and trailing whitespace is
762	     * stripped, every run of internal whitespace is collapsed to a single space, the value is
763	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
764	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). For example {@code "  12  main  st "} normalizes to
765	     * {@code "12 MAIN STREET"}. A {@code null} value normalizes to the empty string. This is the form
766	     * that is stored, returned, and used for every address comparison (household duplicate detection
767	     * and the shared household id).
768	     *
769	     * @param address the raw address value from the submitted owner payload, may be {@code null}
770	     * @return the normalized address
771	     */
772	    private String normalizeAddress(String address) {
773	        if (address == null) {
774	            return "";
775	        }
776	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
777	        if (collapsed.isEmpty()) {
778	            return "";
779	        }
780	        String[] tokens = collapsed.split(" ");
781	        StringBuilder normalized = new StringBuilder();
782	        for (int i = 0; i < tokens.length; i++) {
783	            if (i > 0) {
784	                normalized.append(' ');
785	            }
786	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
787	        }
788	        return normalized.toString();
789	    }
790	}
